  align-items: flex-start;
  gap: 8px;
  font-size: 15px;
  color: #e0e0e0;
  cursor: pointer;
  line-height: 1.5;
}

label a {
  color: #64b5f6;
  text-decoration: none;
  border-bottom: 1px solid #64b5f6;
  transition: color 0.2s;
}

label a:hover {
  color: #90caf9;
}

label a:focus {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
  border-radius: 2px;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  min-width: 20px;
  margin-top: 2px;
  cursor: pointer;
  accent-color: #64b5f6;
}

input[type="checkbox"]:focus {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

input[type="checkbox"]:focus:not(:focus-visible) {
  outline: none;
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

.required {
  color: #ff6b6b;
  font-weight: 600;
}

.helper-text {
  font-size: 13px;
  color: #909090;
  line-height: 1.4;
  margin: 0;
}

.error-message {
  font-size: 13px;
  color: #ff6b6b;
  line-height: 1.4;
  margin: 0;
}

input[type="checkbox"]:invalid {
  border-color: #ff6b6b;
}

.submit-button {
  background: linear-gradient(135deg, #64b5f6 0%, #42a5f5 100%);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  margin-top: 8px;
}

.submit-button:hover {
  background: linear-gradient(135deg, #90caf9 0%, #64b5f6 100%);
  box-shadow: 0 8px 24px rgba(100, 181, 246, 0.3);
}

.submit-button:active {
  transform: translateY(1px);
}

.submit-button:focus {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

