+class ConsentForm {
+  constructor() {
+    this.form = document.getElementById('consentForm');
+    this.checkbox = document.getElementById('agreeTerms');
+    this.errorMessage = document.getElementById('agreeTerms-error');
+    
+    this.init();
+  }
+
+  init() {
+    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+    this.checkbox.addEventListener('change', () => this.clearError());
+  }
+
+  handleSubmit(event) {
+    event.preventDefault();
+
+    if (!this.checkbox.checked) {
+      this.showError();
+      this.checkbox.focus();
+      return;
