+  }
+
+  showError() {
+    this.checkbox.setAttribute('aria-invalid', 'true');
+    this.errorMessage.hidden = false;
+  }
+
+  clearError() {
+    this.checkbox.setAttribute('aria-invalid', 'false');
+    this.errorMessage.hidden = true;
+  }
+}
