* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: linear-gradient(135deg, #0f0f0f 0%, #1a1a1a 100%);
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.consent-container {
  width: 100%;
  max-width: 480px;
}

.consent-card {
  background: #1e1e1e;
  border: 1px solid #333;
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 28px;
  font-weight: 600;
  margin-bottom: 12px;
  color: #fff;
}

.consent-intro {
  font-size: 14px;
  color: #a0a0a0;
  margin-bottom: 32px;
  line-height: 1.5;
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.form-field {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  gap: 8px;
}

label {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 15px;
  color: #e0e0e0;
  cursor: pointer;
  line-height: 1.5;
}

label a {
  color: #64b5f6;
  text-decoration: none;
  border-bottom: 1px solid #64b5f6;
  transition: color 0.2s;
}

label a:hover {
  color: #90caf9;
}

label a:focus {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
  border-radius: 2px;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  min-width: 20px;
  margin-top: 2px;
  cursor: pointer;
  accent-color: #64b5f6;
}

input[type="checkbox"]:focus {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

input[type="checkbox"]:focus:not(:focus-visible) {
  outline: none;
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

.required {
  color: #ff6b6b;
  font-weight: 600;
}

.helper-text {
  font-size: 13px;
  color: #909090;
  line-height: 1.4;
  margin: 0;
}

.error-message {
  font-size: 13px;
  color: #ff6b6b;
  line-height: 1.4;
  margin: 0;
}

input[type="checkbox"]:invalid {
  border-color: #ff6b6b;
}

.submit-button {
  background: linear-gradient(135deg, #64b5f6 0%, #42a5f5 100%);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 12px 24px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  margin-top: 8px;
}

.submit-button:hover {
  background: linear-gradient(135deg, #90caf9 0%, #64b5f6 100%);
  box-shadow: 0 8px 24px rgba(100, 181, 246, 0.3);
}

.submit-button:active {
  transform: translateY(1px);
}

.submit-button:focus {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

.submit-button:focus:not(:focus-visible) {
  outline: none;
}

.submit-button:focus-visible {
  outline: 2px solid #64b5f6;
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}

@media (prefers-color-scheme: light) {
  body {
    background: linear-gradient(135deg, #f5f5f5 0%, #e8e8e8 100%);
    color: #333;
  }

  .consent-card {
    background: #fff;
    border: 1px solid #ddd;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.1);
  }

  h1 {
    color: #000;
  }

  .consent-intro {
    color: #666;
  }

  label {
    color: #333;
  }

  .helper-text {
    color: #666;
  }
}

@media (max-width: 480px) {
  .consent-card {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
  }

  label {
    font-size: 14px;
  }

  .submit-button {
    padding: 10px 16px;
    font-size: 14px;
  }
}
